import unittest
import hourglass.timesheet
import hourglass.parsing
import hourglass.models


class TimesheetTests(unittest.TestCase):
    def test_empty_list_raises(self):
        """An empty schedule has no timesheet to write."""
        with self.assertRaises(ValueError):
            hourglass.timesheet.timesheet_lines([])

    def test_blank_worker_raises(self):
        """A shift with a blank worker name is refused."""
        shifts = [
            hourglass.models.Shift(
                " ", "mon", hourglass.parsing.parse_span("09:00-10:00")
            )
        ]
        with self.assertRaises(ValueError):
            hourglass.timesheet.timesheet_lines(shifts)

    def test_hours_to_one_decimal(self):
        """Hours are shown to one decimal place."""
        shifts = [
            hourglass.models.Shift(
                "Amir", "mon", hourglass.parsing.parse_span("09:00-09:20")
            )
        ]
        self.assertEqual(
            hourglass.timesheet.timesheet_lines(shifts),
            ["Amir: 1 shifts, 0.3 hours"],
        )

    def test_busiest_worker_first(self):
        """Workers with more hours come before workers with fewer."""
        shifts = [
            hourglass.models.Shift(
                "Amir", "mon", hourglass.parsing.parse_span("09:00-10:00")
            ),
            hourglass.models.Shift(
                "Zed", "mon", hourglass.parsing.parse_span("09:00-10:00")
            ),
            hourglass.models.Shift(
                "Zed", "tue", hourglass.parsing.parse_span("09:00-10:00")
            ),
        ]
        self.assertEqual(
            hourglass.timesheet.timesheet_lines(shifts),
            ["Zed: 2 shifts, 2.0 hours", "Amir: 1 shifts, 1.0 hours"],
        )
